import{_ as t,o as l,c as e,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"恶意代码分析","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/恶意代码分析.md","filePath":"安全方向/恶意代码分析.md","lastUpdated":1792430298000}'),i={name:"安全方向/恶意代码分析.md"};function d(o,a,h,n,s,c){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="恶意代码分析" tabindex="-1">恶意代码分析 <a class="header-anchor" href="#恶意代码分析" aria-label="Permalink to &quot;恶意代码分析&quot;">​</a></h1><blockquote><p>校内对应「计算机病毒原理与防范」（第 4 学期，核心课）。恶意代码分析是安全运营、应急响应、威胁情报的核心能力。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>病毒、木马、勒索软件是安全事件的直接元凶，分析师必须「解剖」它们；</li><li>应急响应岗位的核心工作：发现样本 → 分析行为 → 清除与溯源；</li><li>学院在计算机病毒、信息内容安全方向有深厚师资积累（王长缨教授等）。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../必学工具/逆向工具链.html">逆向工具链</a>、<a href="./二进制安全与逆向.html">二进制安全与逆向</a></li><li><a href="./../专业基础/操作系统.html">操作系统</a>（进程、注册表/启动项概念）</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>恶意代码分类：病毒、蠕虫、木马、勒索、间谍、Rootkit</li><li>分析流程：静态分析 → 动态分析 → 行为分析 → 报告</li><li>静态手段：查壳、字符串、导入表、反汇编（对应课程「病毒原理」）</li><li>动态手段：沙箱运行、网络行为监控（抓包）、进程/文件行为监控</li><li>免杀与检测对抗概念：加壳、混淆、反调试</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《恶意代码分析实战》（Practical Malware Analysis）</td><td>书</td><td>恶意代码分析领域圣经，含配套实验</td></tr><tr><td>《计算机病毒分析与对抗》</td><td>拓展</td><td>中文病毒分析读物</td></tr><tr><td>ANY.RUN / Virustotal（<a href="https://www.virustotal.com/" target="_blank" rel="noreferrer">virustotal.com</a>）</td><td>在线平台</td><td>沙箱与多引擎检测</td></tr><tr><td>Malware-Traffic-Analysis.net</td><td>练习</td><td>真实流量样本分析练习</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>安全第一</strong>：分析样本必须用隔离虚拟机（<a href="./../必学工具/虚拟机与Kali.html">虚拟机与 Kali</a>），断网或模拟网络，严禁在真机运行；</li><li>从「分析一个已知样本」开始：下载公开样本集（如 Malware-Traffic-Analysis），写分析报告；</li><li>与 <a href="./数字取证.html">数字取证</a> 配合，形成「样本 → 行为 → 溯源」完整链条。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>计算机病毒原理与防范（第 4 学期，核心课）</li><li>信息内容安全 / 网络舆情安全技术（主干课程）</li></ul>',14)])])}const f=t(i,[["render",d]]);export{_ as __pageData,f as default};
